	/** Built-in blocks plus the ones typed in the block list. */
	private void rebuildKinds() {
		Map<Block, Kind> map = new IdentityHashMap<>(BUILT_IN);
		for (String id : custom.ids()) {
			Identifier key = Identifier.tryParse(id);
			if (key == null) continue;
			BuiltInRegistries.BLOCK.getOptional(key).ifPresent(b -> { if (b != Blocks.AIR) map.put(b, new Kind(Group.CUSTOM, 3, false, null, false)); });
		}
		kinds = map;
		Map<Block, Kind> k = map;
		scanner.setClassifier(st -> {
			Kind kind = k.get(st.getBlock());
			if (kind != null) return kind;
			// lava casts: flowing (not source) lava next to a base is a griefing sign
			if (st.getBlock() == Blocks.LAVA && !st.getFluidState().isSource()) return FLOWING_LAVA;
			return null;
		});
	}

	/** True while BaseValue runs the base search with this module switched off (no highlights, labels or chat). */
	private boolean driven;

	/** BaseValue's background base search: scans and finds bases while the module itself stays off. */
	public void drive(boolean on) {
		if (on == driven) return;
		driven = on;
		if (!on && !isEnabled()) resetScan();
	}

	/** Called every tick by BaseValue while it drives the search and the module is off. */
	public void backgroundTick() { if (driven && !isEnabled()) onTick(); }

	@Override
	public void onTick() {
		ClientLevel level = mc.level;
		if (level == null || mc.player == null) return;
		if (level != lastLevel) { lastLevel = level; announced.clear(); }
		if (!custom.get().equals(lastCustom)) { lastCustom = custom.get(); rebuildKinds(); }
		if (raidWords.get().equals(OLD_RAID_WORDS)) raidWords.set(DEFAULT_RAID_WORDS);
		tick++;
		long t0 = com.wailsvlr.prism.util.Perf.start();
		boolean scanned = scanner.tick(level, mc.player.blockPosition(), new ChunkScanner.Options(
			BlockEntityScanner.chunkRadius(range.get()), level.getMinY(), level.getMaxY(), fastScan ? Math.max(16, chunksPerTick.getInt()) : chunksPerTick.getInt(),
			refreshSeconds.getInt() * 20L, false));
		com.wailsvlr.prism.util.Perf.end("  BlockFinder scan", t0);
		// the lists are made again only when the scan results changed, you moved 4+ blocks, or 5 s went by
		BlockPos here = mc.player.blockPosition();
		boolean moved = lastRebuildPos == null || lastRebuildPos.distManhattan(here) >= 4;
		if (scanner.version() != lastVersion || moved || tick - lastRebuildTick >= 100 || (basesDirty && tick - lastBasesTick >= 20)) {
			long t1 = com.wailsvlr.prism.util.Perf.start();
			if (tick - lastDropTick >= 200) { scanner.dropChanged(level); lastDropTick = tick; }   // a safety net; block events do this normally
			if (scanner.version() != lastVersion || tick - lastRebuildTick >= 100) basesDirty = true;
			// the base search at most once a second (walking loads new chunks all the time)
			boolean basesNow = basesDirty && tick - lastBasesTick >= 20;
			if (basesNow) { basesDirty = false; lastBasesTick = tick; }
			rebuild(level, basesNow);
			lastVersion = scanner.version();
			lastRebuildPos = here;
			lastRebuildTick = tick;
			com.wailsvlr.prism.util.Perf.end("  BlockFinder rebuild", t1);
		}
	}

	/** Called for every block change on the client (see ClientLevelMixin). */
